// Кейс: .qa/tests/monitoring/MON-014.md · план: .qa/e2e-app/specs/app.md (1.14)
// Мониторинг → приложение в фон (mobile: backgroundApp) → возврат → лист «הניטור הופסק» → «המשך ניטור» → «תקין», таймер идёт,
// в «היסטוריית אירועים» — «האפליקציה ירדה לרקע», «המצלמה הפסיקה לפעול», «הניטור חזר לפעול» → «כבה את המצלמה».
// ЗАПУСКАЕТ МОНИТОРИНГ (сеанс в «היסטוריה») — только с BANCI_MONITORING=1. Блокировка экрана, уведомление
// на экране блокировки, звук, быстрый возврат < 2 с и авиарежим — вручную (MON-014).
import { by, assert } from '../../lib/appium.mjs';
import { requireMonitoringOptIn, startMonitoring, endMonitoring, timerSeconds, waitTimer } from '../../lib/monitoring.mjs';

export const name = 'Мониторинг → фон → возврат → лист «הניטור הופסק» → «המשך ניטור» → «תקין», события «האפליקציה ירדה לרקע» / «הניטור חזר לפעול» #0b59fe @iphone @app @data';

export default async function (app) {
  requireMonitoringOptIn();
  await startMonitoring(app);
  await waitTimer(app, 5);

  // 1. Уход в фон на 6 с (больше порога ~3 с), затем возврат.
  await app.exec('mobile: backgroundApp', { seconds: 6 });
  await app.activate();

  // 2. Лист «הניטור הופסק» (источник: проверка 25.10, скриншот 2026-10-25_0b59fe_background_notification-tap_sheet.png).
  await app.waitFor(by.contains('הניטור הופסק'), { timeout: 15000, what: 'лист «הניטור הופסק» после возврата из фона' });
  await app.waitFor(by.contains('המסך ננעל או שהאפליקציה נסגרה, ובזמן הזה הבריכה לא הייתה במעקב'), { what: 'текст «המסך ננעל או שהאפליקציה נסגרה, ובזמן הזה הבריכה לא הייתה במעקב. הניטור חזר לפעול עכשיו.»' });
  for (const step of ['השאירו את Banci פתוחה', 'אל תנעלו את הטלפון בכפתור הצד', 'חברו את הטלפון למטען']) {
    await app.waitFor(by.contains(step), { what: `шаг «${step}…» в листе` });
  }
  await app.waitFor(by.exact('סיום ניטור'), { what: 'кнопка «סיום ניטור» в листе' });
  const resume = await app.waitFor(by.exact('המשך ניטור'), { what: 'кнопка «המשך ניטור» в листе' });

  // 3. «המשך ניטור» → лист закрыт, статус «תקין», таймер растёт.
  await resume.click();
  await app.waitGone(by.contains('הניטור הופסק'), { what: 'лист «הניטור הופסק» закрылся после «המשך ניטור»' });
  await app.waitFor(by.exact('תקין'), { timeout: 20000, what: 'статус «תקין» после «המשך ניטור»' });
  const t0 = await timerSeconds(app);
  const t1 = await waitTimer(app, t0 + 3);
  assert(t1 > t0, `таймер мониторинга растёт после возврата (${t0} → ${t1} с)`);

  // 4. «היסטוריית אירועים»: события разрыва и восстановления.
  for (const ev of ['האפליקציה ירדה לרקע', 'המצלמה הפסיקה לפעול', 'הניטור חזר לפעול']) {
    await app.scrollTo(by.contains(ev), { what: `событие «${ev}» в «היסטוריית אירועים»` });
  }
  await app.scrollTo(by.contains('כבה את המצלמה'), { direction: 'up', what: 'слайдер «כבה את המצלמה»' }).catch(() => {});

  // 5. Завершить мониторинг (сеанс в истории — тестовые данные).
  await endMonitoring(app);
}
